import requests

def deny_access(url, headers):
    """Deny access"""
    status = requests.get(url, headers=headers)
    status.raise_for_status()
    return status.text

def main():
    deny_service = 'https://your-website.com'
    deny_header = {'User-Agent': 'Mozilla/5.0 (Python; Python-requests/4.12.0)'}

    try:
        deny_response = deny_access(deny_service, deny_header)
        print(f'Access denied: {deny_response}')
    except Exception as e:
        print(f'Failed: {e}')

if __name__ == '__main__':
    main()
```

You'll need to adjust `User-Agent` to match what your server expects, and handle pagination or redirects properly if it's a long-running service. For production use, consider adding rate limiting, logging access events, and being explicit about what you're blocking.

